<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function pupil_lifecycle_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())pupil_lifecycle_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))pupil_lifecycle_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher'],true))pupil_lifecycle_json(403,['ok'=>false,'message'=>'Only school leadership can access pupil enrolment history.']);if($_SERVER['REQUEST_METHOD']==='GET'){$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$pupil=filter_var($_GET['pupil_id']??null,FILTER_VALIDATE_INT);if(!$school||!$pupil)pupil_lifecycle_json(422,['ok'=>false,'message'=>'Choose a school and pupil.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())pupil_lifecycle_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$q=$db->prepare('SELECT h.previous_status,h.new_status,h.effective_date,h.note,h.created_at,u.name changed_by FROM pupil_status_history h JOIN pupils p ON p.id=h.pupil_id AND p.school_id=h.school_id JOIN users u ON u.id=h.changed_by WHERE h.school_id=? AND h.pupil_id=? ORDER BY h.effective_date DESC,h.id DESC');$q->execute([$school,$pupil]);pupil_lifecycle_json(200,['ok'=>true,'data'=>['history'=>$q->fetchAll()]]);}if($_SERVER['REQUEST_METHOD']!=='POST')pupil_lifecycle_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))pupil_lifecycle_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);
$uid=(int)$_SESSION['user_id'];$school=filter_var($_POST['school_id']??null,FILTER_VALIDATE_INT);$pupil=filter_var($_POST['pupil_id']??null,FILTER_VALIDATE_INT);$new=(string)($_POST['new_status']??'');$date=(string)($_POST['effective_date']??'');$note=trim((string)($_POST['note']??''));if(!$school||!$pupil||!in_array($new,['active','transferred','graduated'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))||$date>date('Y-m-d')||mb_strlen($note)>500)pupil_lifecycle_json(422,['ok'=>false,'message'=>'Choose a valid status and effective date; notes may be up to 500 characters.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())pupil_lifecycle_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
try{$db->beginTransaction();$q=$db->prepare('SELECT id,status,admission_number FROM pupils WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$pupil,$school]);$student=$q->fetch();if(!$student)throw new DomainException('Pupil not found in this school.');$old=(string)$student['status'];if($old===$new)throw new DomainException('The pupil already has this enrolment status.');if($old!=='active'&&$new!=='active')throw new DomainException('A former pupil can only be reactivated before another status change.');$q=$db->prepare('SELECT effective_date FROM pupil_status_history WHERE pupil_id=? AND school_id=? ORDER BY effective_date DESC,id DESC LIMIT 1');$q->execute([$pupil,$school]);$lastDate=$q->fetchColumn();if($lastDate!==false&&$date<=(string)$lastDate)throw new DomainException('The new status effective date must be later than the previous status change.');$q=$db->prepare('INSERT INTO pupil_status_history(pupil_id,school_id,previous_status,new_status,effective_date,note,changed_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$pupil,$school,$old,$new,$date,$note?:null,$uid]);$historyId=(int)$db->lastInsertId();$update=$db->prepare('UPDATE pupils SET status=? WHERE id=? AND school_id=? AND status=?');$update->execute([$new,$pupil,$school,$old]);if($update->rowCount()!==1)throw new DomainException('Pupil status changed concurrently. Refresh and try again.');$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'change_enrolment_status','pupil',$pupil,json_encode(['school_id'=>$school,'admission_number'=>$student['admission_number'],'previous_status'=>$old,'new_status'=>$new,'effective_date'=>$date,'note'=>$note?:null,'history_id'=>$historyId],JSON_THROW_ON_ERROR)]);$db->commit();pupil_lifecycle_json(200,['ok'=>true,'message'=>'Pupil enrolment status updated.','data'=>['pupil_id'=>$pupil,'status'=>$new,'effective_date'=>$date]]);}catch(DomainException $e){if($db->inTransaction())$db->rollBack();pupil_lifecycle_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Pupil lifecycle update failed: '.$e->getMessage());pupil_lifecycle_json(500,['ok'=>false,'message'=>'Pupil status could not be saved. Verify the status-history migration.']);}
